#include "isr.h"
#include "sys_private.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void sys_timer_init (void)
{
  /// Setup TIMER-0 for 1 ms IRQ. For testing, we assume 72 MHz clock and divider is 1 ///
  
  PCONP |= (1u << 1) ;

  /// Setup TIMER-0 for 1 ms IRQ. For testing, we assume 72 MHz clock and divider is 1 ///

  PCLKSEL0 &= ~(3u << 2) ;
  PCLKSEL0 |=  (1u << 2) ;    // Divide CPU clock by 1

  T0PC   = 0x00000000 ;       // Set prescaler to divide by 1

  T0MR0  = 72000 - 1  ;       // Set match limit

  T0MCR |= 0x03 ;             // On match 0, generate IRQ and reset timer counter   
  T0TCR  = 0x01 ;             // Enable TIMER-0
  
  /// Hook into VIC interrupt controller ///

  isr_set_vector (ISR_ID_TIMER_0 , ISR_PRI_15 , ISR_TYPE_IRQ , sys_irq_timer_service) ;

}

